-- Seed all Polish vocabulary (pl_001 through pl_210) into vocab and vocab_translation tables.
-- The theme_vocab mappings for pl_theme10/11 are seeded in 012 (which
-- inserts the theme rows first so the FKs are satisfied).

-- Widen vocab.gender to allow 'n' (neutral). The 001 baseline only
-- allows 'm'/'f', but pl_211+ in 013 use 'n' for neuter nouns.
ALTER TABLE vocab DROP CONSTRAINT IF EXISTS vocab_gender_check;
ALTER TABLE vocab ADD CONSTRAINT vocab_gender_check
  CHECK (gender IS NULL OR gender IN ('m', 'f', 'n'));

